--- /dev/null
+++ b/src/retry.ts
@@ -0,0 +1,33 @@
+export interface RetryOptions {
+  retries: number;
+  baseDelayMs?: number;
+  maxDelayMs?: number;
+  /** Injected for tests. */
+  sleep?: (ms: number) => Promise<void>;
+  random?: () => number;
+}
+
+const RETRYABLE_CODES = new Set(['ECONNRESET', 'ETIMEDOUT', 'EAI_AGAIN', 'EPIPE']);
+
+/** Network errors and 5xx replies are worth another try; 4xx (bad key, no permission) never are. */
+export function isRetryable(err: unknown): boolean {
+  const e = err as { code?: string; status?: number };
+  if (e.code && RETRYABLE_CODES.has(e.code)) return true;
+  return typeof e.status === 'number' && e.status >= 500;
+}
+
+export async function withRetry<T>(fn: () => Promise<T>, opts: RetryOptions): Promise<{ value: T; attempts: number }> {
+  const base = opts.baseDelayMs ?? 200;
+  const max = opts.maxDelayMs ?? 10_000;
+  const sleep = opts.sleep ?? ((ms) => new Promise<void>((r) => setTimeout(r, ms)));
+  const random = opts.random ?? Math.random;
+  for (let attempt = 1; ; attempt++) {
+    try {
+      return { value: await fn(), attempts: attempt };
+    } catch (err) {
+      if (attempt > opts.retries || !isRetryable(err)) throw err;
+      const delay = Math.min(max, base * 2 ** (attempt - 1));
+      await sleep(delay / 2 + random() * (delay / 2));
+    }
+  }
+}

