diff --git a/test/retry.test.ts b/test/retry.test.ts
new file mode 100644
--- /dev/null
+++ b/test/retry.test.ts
@@ -0,0 +1,38 @@
+import { describe, expect, it } from 'vitest';
+import { isRetryable, withRetry } from '../src/retry.js';
+
+const noSleep = async () => undefined;
+
+describe('withRetry', () => {
+  it('retries a network error and returns the attempt count', async () => {
+    let calls = 0;
+    const r = await withRetry(async () => {
+      if (++calls < 3) throw Object.assign(new Error('reset'), { code: 'ECONNRESET' });
+      return 'ok';
+    }, { retries: 3, sleep: noSleep });
+    expect(r).toEqual({ value: 'ok', attempts: 3 });
+  });
+
+  it('never retries a 4xx reply', async () => {
+    let calls = 0;
+    await expect(withRetry(async () => { calls++; throw Object.assign(new Error('denied'), { status: 403 }); }, { retries: 3, sleep: noSleep }))
+      .rejects.toThrow('denied');
+    expect(calls).toBe(1);
+  });
+
+  it('doubles the delay up to the cap, with jitter in the upper half', async () => {
+    const delays: number[] = [];
+    await withRetry(async () => { throw Object.assign(new Error('x'), { status: 503 }); }, {
+      retries: 4, baseDelayMs: 100, maxDelayMs: 300, sleep: async (ms) => { delays.push(ms); }, random: () => 1,
+    }).catch(() => undefined);
+    expect(delays).toEqual([100, 200, 300, 300]);
+  });
+});
+
+describe('isRetryable', () => {
+  it('accepts 5xx and connection errors only', () => {
+    expect(isRetryable({ status: 502 })).toBe(true);
+    expect(isRetryable({ code: 'ETIMEDOUT' })).toBe(true);
+    expect(isRetryable({ status: 404 })).toBe(false);
+  });
+});

